import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';

export default class WorkItemActionBar extends NavigationMixin(LightningElement) {
    @api workItemId;

    /**
     * Handle Edit action
     * Dispatches event to parent to enter inline edit mode
     */
    handleEdit() {
        // Dispatch event to parent to enter edit mode
        this.dispatchActionEvent('Edit');
    }

    /**
     * Handle Add Child action
     * Dispatches event to parent to open create modal
     */
    handleAddChild() {
        // Dispatch event to parent to open create modal
        this.dispatchActionEvent('Add Child');
    }

    /**
     * Handle Add Note action
     * Dispatches event to parent to open note modal
     */
    handleAddNote() {
        // Dispatch event to parent to open note modal
        this.dispatchActionEvent('Add Note');
    }

    /**
     * Handle Delete action
     * Dispatches event to parent to open delete confirmation modal
     */
    handleDelete() {
        // Dispatch event to parent to open delete confirmation modal
        this.dispatchActionEvent('Delete');
    }

    /**
     * Dispatch action executed event to parent component
     */
    dispatchActionEvent(actionName) {
        const event = new CustomEvent('actionexecuted', {
            detail: {
                actionName,
                workItemId: this.workItemId
            },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(event);
    }
}

