import { api, track } from 'lwc';
import { updateRecord } from 'lightning/uiRecordApi';
import ID_FIELD from '@salesforce/schema/Work_Item__c.Id';
import START_DATE_FIELD from '@salesforce/schema/Work_Item__c.Start_Date__c';
import DUE_DATE_FIELD from '@salesforce/schema/Work_Item__c.Due_Date__c';
import BaseComponent from 'c/baseComponent';

export default class WorkItemGanttBar extends BaseComponent {
    @api workItem;
    @api timelineBounds;

    @track isDragging = false;
    @track isResizing = false;
    @track dragStartX = 0;
    @track originalLeft = 0;
    @track originalWidth = 0;
    @track originalStartOffsetDays = 0;
    @track resizeEdge = null; // 'left' or 'right'
    @track tempLeft = null; // Temporary position during drag
    @track tempWidth = null; // Temporary width during resize
    @track tempStartDate = null; // Temporary start date during drag/resize
    @track tempDueDate = null; // Temporary due date during drag/resize

    // Computed properties
    get scale() {
        return this.timelineBounds?.scale || 'week';
    }

    get columnWidthInPixels() {
        // Column width in pixels based on scale
        if (this.scale === 'day') {
            return 80;
        }
        if (this.scale === 'week') {
            return 160;
        }
        if (this.scale === 'month') {
            return 360;
        }
        return 160;
    }

    get columnWidthInDays() {
        // How many days each column represents
        if (this.scale === 'day') {
            return 1;
        }
        if (this.scale === 'week') {
            return 7;
        }
        if (this.scale === 'month') {
            return 30;
        } // Approximate
        return 7;
    }

    get pixelsPerDay() {
        // Calculate pixels per day for smooth day-by-day dragging
        return this.columnWidthInPixels / this.columnWidthInDays;
    }

    get barPosition() {
        if (!this.workItem.startDate || !this.workItem.dueDate || !this.timelineBounds) {
            return null;
        }

        const startDate = this.parseLocalDate(this.workItem.startDate);
        const dueDate = this.parseLocalDate(this.workItem.dueDate);
        let timelineStart = this.parseLocalDate(this.timelineBounds.minDate);

        // In week view, timeline starts on Monday of the week containing minDate
        if (this.scale === 'week') {
            const dayOfWeek = timelineStart.getDay();
            const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
            timelineStart = new Date(timelineStart.getFullYear(), timelineStart.getMonth(), timelineStart.getDate() + daysToMonday);
        } else if (this.scale === 'month') {
            // In month view, timeline starts on 1st of the month containing minDate
            timelineStart = new Date(timelineStart.getFullYear(), timelineStart.getMonth(), 1);
        }

        // Calculate position and width in days
        const startOffsetDays = Math.floor((startDate - timelineStart) / (1000 * 60 * 60 * 24));
        const durationDays = Math.floor((dueDate - startDate) / (1000 * 60 * 60 * 24)) + 1;

        // Convert directly from days to pixels for accurate positioning
        const pixelsPerDay = this.pixelsPerDay;
        const leftPx = startOffsetDays * pixelsPerDay;
        const widthPx = Math.max(durationDays * pixelsPerDay, pixelsPerDay); // Minimum 1 day width

        return {
            left: leftPx,
            width: widthPx,
            startOffsetDays,
            durationDays
        };
    }

    get barStyle() {
        if (!this.barPosition) {
            return 'display: none;';
        }

        // Use temporary position/width during drag/resize, otherwise use calculated position
        const left = this.tempLeft !== null ? this.tempLeft : this.barPosition.left;
        const width = this.tempWidth !== null ? this.tempWidth : this.barPosition.width;

        return `left: ${left}px; width: ${width}px;`;
    }

    get barClass() {
        const classes = ['gantt-bar'];

        // Status-based coloring
        const variant = this.workItem.workflow?.find((status) => status.name === this.workItem.status)?.variant || 'neutral';
        classes.push(`bar-${variant}`);

        // Blocked takes highest priority
        if (this.workItem.isBlocked) {
            classes.push('highlight-blocked');
        }
        // At Risk takes next priority
        else if (this.workItem.isAtRisk) {
            classes.push('highlight-at-risk');
        }
        // Other highlight classes
        else if (this.workItem.highlights && this.workItem.highlights.length > 0) {
            this.workItem.highlights.forEach((highlight) => {
                classes.push(`highlight-${highlight}`);
            });
        }

        // Check if overdue
        if (this.isOverdue) {
            classes.push('bar-overdue');
        }

        // Dragging/resizing states
        if (this.isDragging) {
            classes.push('dragging');
        }
        if (this.isResizing) {
            classes.push('resizing');
        }

        return classes.join(' ');
    }

    get isOverdue() {
        if (
            !this.workItem.dueDate ||
            this.workItem.status === 'Complete' ||
            this.workItem.workflow?.find((status) => status.name === this.workItem.status)?.variant === 'success'
        ) {
            return false;
        }
        const today = new Date();
        const dueDate = new Date(this.workItem.dueDate);
        return dueDate < today;
    }

    get progressPercentage() {
        const estimated = this.workItem.estimatedHours || 0;
        const actual = this.workItem.actualHours || 0;
        if (estimated === 0) {
            return 0;
        }
        return Math.min(100, Math.round((actual / estimated) * 100));
    }

    get progressStyle() {
        return `width: ${this.progressPercentage}%;`;
    }

    get tooltipContent() {
        let tooltip =
            `${this.workItem.name}\n` +
            `Status: ${this.workItem.status || 'Not Started'}\n` +
            `Start: ${this.formatDate(this.workItem.startDate)}\n` +
            `Due: ${this.formatDate(this.workItem.dueDate)}`;

        // Add blocked message if applicable
        if (this.workItem.isBlocked) {
            const blockedMsg = this.workItem.blockedDetails || 'This work item is blocked';
            tooltip += `\n\n🚫 BLOCKED: ${blockedMsg}`;
        }

        // Add at-risk message if applicable
        if (this.workItem.isAtRisk) {
            const atRiskMsg = this.workItem.atRiskDetails || 'This work item requires attention';
            tooltip += `\n\n⚠️ AT RISK: ${atRiskMsg}`;
        }

        return tooltip;
    }

    get showDateTooltip() {
        return (this.isDragging || this.isResizing) && this.tempStartDate && this.tempDueDate;
    }

    get dateTooltipText() {
        if (!this.tempStartDate || !this.tempDueDate) {
            return '';
        }
        const startStr = this.formatDateLocal(this.tempStartDate);
        const dueStr = this.formatDateLocal(this.tempDueDate);
        return `${startStr} - ${dueStr}`;
    }

    // Drag handlers - Move entire bar
    handleBarMouseDown(event) {
        if (event.button !== 0) {
            return;
        } // Only left mouse button

        // Check if clicking on resize handle
        const rect = event.currentTarget.getBoundingClientRect();
        const clickX = event.clientX - rect.left;

        if (clickX < 10) {
            // Left edge resize
            this.startResize(event, 'left');
        } else if (clickX > rect.width - 10) {
            // Right edge resize
            this.startResize(event, 'right');
        } else {
            // Move entire bar
            this.startDrag(event);
        }
    }

    startDrag(event) {
        this.isDragging = true;
        this.dragStartX = event.clientX;
        this.originalLeft = this.barPosition.left;
        this.originalStartOffsetDays = this.barPosition.startOffsetDays; // Store exact days offset

        document.addEventListener('mousemove', this.handleDragMove);
        document.addEventListener('mouseup', this.handleDragEnd);
    }

    handleDragMove = (event) => {
        if (!this.isDragging) {
            return;
        }

        const deltaX = event.clientX - this.dragStartX;
        const newLeft = this.originalLeft + deltaX;
        const pixelsPerDay = this.pixelsPerDay;

        // Calculate new start offset in days (snapped to day increments)
        const newStartOffsetDays = Math.round(newLeft / pixelsPerDay);

        // Update temporary position (will trigger re-render via barStyle getter)
        this.tempLeft = newStartOffsetDays * pixelsPerDay;

        // Calculate temporary dates for tooltip
        const deltaDays = newStartOffsetDays - this.originalStartOffsetDays;

        if (deltaDays !== 0) {
            const originalStart = this.parseLocalDate(this.workItem.startDate);
            const originalDue = this.parseLocalDate(this.workItem.dueDate);

            this.tempStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate() + deltaDays);
            this.tempDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate() + deltaDays);
        }
    };

    handleDragEnd = async (event) => {
        if (!this.isDragging) {
            return;
        }

        document.removeEventListener('mousemove', this.handleDragMove);
        document.removeEventListener('mouseup', this.handleDragEnd);

        const deltaX = event.clientX - this.dragStartX;
        const newLeft = this.originalLeft + deltaX;
        const pixelsPerDay = this.pixelsPerDay;

        // Calculate new position in days (snapped to day increments)
        const newStartOffsetDays = Math.round(newLeft / pixelsPerDay);

        // Calculate the actual day delta based on snapped positions
        const deltaDays = newStartOffsetDays - this.originalStartOffsetDays;

        this.isDragging = false;
        this.tempLeft = null; // Clear temp position - component will use fresh data after refresh
        this.tempStartDate = null;
        this.tempDueDate = null;

        if (deltaDays === 0) {
            // No change - just end drag
            return;
        }

        // Calculate new dates using local date math
        const originalStart = this.parseLocalDate(this.workItem.startDate);
        const originalDue = this.parseLocalDate(this.workItem.dueDate);

        // Create new dates by adding days (keeps local time)
        const newStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate() + deltaDays);
        const newDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate() + deltaDays);

        await this.updateWorkItemDates(newStartDate, newDueDate);
    };

    // Resize handlers - Adjust start or end date
    startResize(event, edge) {
        this.isResizing = true;
        this.resizeEdge = edge;
        this.dragStartX = event.clientX;
        this.originalLeft = this.barPosition.left;
        this.originalWidth = this.barPosition.width;

        document.addEventListener('mousemove', this.handleResizeMove);
        document.addEventListener('mouseup', this.handleResizeEnd);
    }

    handleResizeMove = (event) => {
        if (!this.isResizing) {
            return;
        }

        const deltaX = event.clientX - this.dragStartX;
        const pixelsPerDay = this.pixelsPerDay;

        if (this.resizeEdge === 'left') {
            // Adjust start date (left edge)
            const newLeft = this.originalLeft + deltaX;
            const newWidth = this.originalWidth - deltaX;

            if (newWidth >= pixelsPerDay) {
                // Minimum 1 day
                this.tempLeft = Math.round(newLeft / pixelsPerDay) * pixelsPerDay;
                this.tempWidth = Math.round(newWidth / pixelsPerDay) * pixelsPerDay;

                // Calculate temporary start date for tooltip
                const deltaDays = Math.round(deltaX / pixelsPerDay);
                const originalStart = this.parseLocalDate(this.workItem.startDate);
                this.tempStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate() + deltaDays);
                this.tempDueDate = this.parseLocalDate(this.workItem.dueDate);
            }
        } else if (this.resizeEdge === 'right') {
            // Adjust due date (right edge)
            const newWidth = this.originalWidth + deltaX;

            if (newWidth >= pixelsPerDay) {
                // Minimum 1 day
                this.tempWidth = Math.round(newWidth / pixelsPerDay) * pixelsPerDay;

                // Calculate temporary due date for tooltip
                const deltaDays = Math.round(deltaX / pixelsPerDay);
                const originalDue = this.parseLocalDate(this.workItem.dueDate);
                this.tempStartDate = this.parseLocalDate(this.workItem.startDate);
                this.tempDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate() + deltaDays);
            }
        }
    };

    handleResizeEnd = async (event) => {
        if (!this.isResizing) {
            return;
        }

        document.removeEventListener('mousemove', this.handleResizeMove);
        document.removeEventListener('mouseup', this.handleResizeEnd);

        const deltaX = event.clientX - this.dragStartX;
        const pixelsPerDay = this.pixelsPerDay;

        // Calculate how many days we moved (snapped to day increments)
        const deltaDays = Math.round(deltaX / pixelsPerDay);

        this.isResizing = false;
        const edge = this.resizeEdge;
        this.resizeEdge = null;
        this.tempLeft = null; // Clear temp position
        this.tempWidth = null; // Clear temp width
        this.tempStartDate = null;
        this.tempDueDate = null;

        if (deltaDays === 0) {
            // No change - just end resize
            return;
        }

        // Calculate new dates using local date math
        const originalStart = this.parseLocalDate(this.workItem.startDate);
        const originalDue = this.parseLocalDate(this.workItem.dueDate);

        let newStartDate, newDueDate;

        if (edge === 'left') {
            // Adjust start date (keeps local time)
            newStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate() + deltaDays);
            newDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate());

            // Ensure start is before due
            if (newStartDate >= newDueDate) {
                this.showError('Start date must be before due date', 'Invalid Dates');
                return;
            }
        } else if (edge === 'right') {
            // Adjust due date (keeps local time)
            newStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate());
            newDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate() + deltaDays);

            // Ensure due is after start
            if (newDueDate <= newStartDate) {
                this.showError('Due date must be after start date', 'Invalid Dates');
                return;
            }
        }

        await this.updateWorkItemDates(newStartDate, newDueDate);
    };

    // Update work item via LDS
    async updateWorkItemDates(newStartDate, newDueDate) {
        const fields = {};
        fields[ID_FIELD.fieldApiName] = this.workItem.id;
        fields[START_DATE_FIELD.fieldApiName] = this.formatDateForSalesforce(newStartDate);
        fields[DUE_DATE_FIELD.fieldApiName] = this.formatDateForSalesforce(newDueDate);

        const recordInput = { fields };

        try {
            await updateRecord(recordInput);

            // Publish update event via LMS to trigger refresh in all components
            const message = {
                workItemId: this.workItem.id,
                projectId: this.workItem.projectId,
                source: 'gantt', // Indicate this update came from GANTT drag/resize
                changes: {
                    startDate: fields[START_DATE_FIELD.fieldApiName],
                    dueDate: fields[DUE_DATE_FIELD.fieldApiName]
                }
            };

            this.notify('workItemUpdated', message);

            // Also publish refresh message to update other tabs/components
            const refreshMessage = {
                workItemId: this.workItem.id,
                projectId: this.workItem.projectId
            };
            this.notify('refresh', refreshMessage);

            this.showSuccess('Work item dates updated');
        } catch (error) {
            this.showError(error.body?.message || 'Unknown error', 'Error updating dates');

            // Publish refresh message via LMS to revert changes
            const refreshMessage = {
                workItemId: this.workItem.id,
                projectId: this.workItem.projectId
            };
            this.notify('refresh', refreshMessage);
        }
    }

    // Utility methods
    parseLocalDate(dateString) {
        // Parse YYYY-MM-DD as local date (not UTC)
        if (!dateString) {
            return null;
        }
        const [year, month, day] = dateString.split('-');
        return new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
    }

    formatDate(dateString) {
        if (!dateString) {
            return '-';
        }
        const date = this.parseLocalDate(dateString);
        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    }

    formatDateLocal(date) {
        if (!date) {
            return '-';
        }
        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    }

    formatDateForSalesforce(date) {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }
}

