    11→import BaseComponent from 'c/baseComponent';
    12→
    13→export default class ProjectResourceManager extends BaseComponent {
    14→    @api recordId; // Project Id
    15→    @track resourceAssignments = [];
    16→    @track editingAssignment = null;
    17→    @track isAddMode = false;
    18→    @track isLoading = false;
    19→    @track isExpanded = false; // Controls expanded/collapsed state - default to collapsed
    20→
    21→    // Form fields for add/edit
    22→    @track formData = {
    23→        resourceClassification: '',
    24→        defaultRoleId: '',
    25→        accessLevel: '',
    26→        resourceUserId: '',
    27→        resourceContactId: '',
    28→        notes: ''
    29→    };
    30→
    31→    @track projectRoles = [];
    32→    wiredResourceAssignmentsResult;
    33→    wiredProjectRolesResult;
    34→
    35→    connectedCallback() {
    36→        this.isExpanded = this.getLocalState(this.recordId, 'ProjectResourceManager.isExpanded', this.isExpanded);
    37→    }
    38→
    39→    // Wire resource classification picklist
    40→    @wire(getPicklistValues, {
    41→        recordTypeId: '012000000000000AAA',
    42→        fieldApiName: RESOURCE_CLASSIFICATION_FIELD
    43→    })
    44→    resourceClassificationPicklist;
    45→
    46→    // Wire access level picklist
    47→    @wire(getPicklistValues, {
    48→        recordTypeId: '012000000000000AAA',
    49→        fieldApiName: ACCESS_LEVEL_FIELD
    50→    })
    51→    accessLevelPicklist;
    52→
    53→    // Wire project roles
    54→    @wire(getProjectRoles, { projectId: '$recordId' })
    55→    wiredProjectRoles(result) {
    56→        this.wiredProjectRolesResult = result;
    57→        if (result.data) {
    58→            this.projectRoles = result.data;
    59→        } else if (result.error) {
    60→            console.error('Error loading project roles:', result.error);
    61→        }
    62→    }
    63→
    64→    // Wire resource assignments
    65→    @wire(getResourceAssignments, { projectId: '$recordId' })
    66→    wiredResourceAssignments(result) {
    67→        this.wiredResourceAssignmentsResult = result;
    68→        if (result.data) {
    69→            this.resourceAssignments = result.data.map((assignment) => {
    70→                const resourceName = assignment.cgpm__Resource_User__c ? assignment.cgpm__Resource_User__r?.Name : assignment.cgpm__Resource_Contact__r?.Name;
    71→                const formattedStartDate = assignment.cgpm__Start_Date__c ? this.formatDate(assignment.cgpm__Start_Date__c) : '';
    72→                const formattedEndDate = assignment.cgpm__End_Date__c ? this.formatDate(assignment.cgpm__End_Date__c) : '';
    73→
    74→                return {
    75→                    ...assignment,
    76→                    resourceName,
    77→                    formattedStartDate,
    78→                    formattedEndDate,
    79→                    initials: this.getInitials(resourceName),
    80→                    tooltipText: this.getTooltipText({
    81→                        ...assignment,
    82→                        resourceName,
    83→                        formattedStartDate,
    84→                        formattedEndDate
    85→                    })
    86→                };
    87→            });
    88→            this.isLoading = false;
    89→        } else if (result.error) {
    90→            this.showError('Error loading resource assignments: ' + result.error.body.message);
    91→            this.isLoading = false;
    92→        }
    93→    }
    94→
    95→    get hasAssignments() {
    96→        return this.resourceAssignments && this.resourceAssignments.length > 0;
    97→    }
    98→
    99→    get isFormOpen() {
   100→        return this.isAddMode || this.editingAssignment !== null;
   101→    }
   102→
   103→    get formTitle() {
   104→        return this.isAddMode ? 'Add Resource Assignment' : 'Edit Resource Assignment';
   105→    }
   106→
   107→    get saveButtonLabel() {
   108→        return this.isAddMode ? 'Add' : 'Save';
   109→    }
