import { api } from 'lwc';
import createNote from '@salesforce/apex/WorkItemNoteController.createNote';
import BaseComponent from 'c/baseComponent';

export default class WorkItemNoteModal extends BaseComponent {
    @api workItemId;
    @api workItemName;

    isOpen = false;
    noteText = '';
    isSaving = false;

    /**
     * Open the modal
     */
    @api
    open() {
        this.isOpen = true;
        this.noteText = '';
    }

    /**
     * Close the modal
     */
    handleClose() {
        this.isOpen = false;
        this.noteText = '';
    }

    /**
     * Handle note text change
     */
    handleNoteChange(event) {
        this.noteText = event.target.value;
    }

    /**
     * Handle save button click
     */
    async handleSave() {
        // Validate note text
        if (!this.noteText || this.noteText.trim().length === 0) {
            this.showError('Please enter note text');
            return;
        }

        if (this.noteText.length > 1000) {
            this.showError('Note text cannot exceed 1000 characters');
            return;
        }

        this.isSaving = true;

        try {
            await createNote({
                workItemId: this.workItemId,
                noteText: this.noteText.trim()
            });

            this.showSuccess('Note added successfully');

            // Dispatch event to notify parent that a note was created
            this.dispatchEvent(
                new CustomEvent('notecreated', {
                    detail: {
                        workItemId: this.workItemId
                    },
                    bubbles: true,
                    composed: true
                })
            );

            // Close modal
            this.handleClose();
        } catch (error) {
            console.error('Error creating note:', error);
            this.showError(error.body?.message || 'Error creating note');
        } finally {
            this.isSaving = false;
        }
    }

    /**
     * Computed property for modal title
     */
    get modalTitle() {
        return `Add Note - ${this.workItemName || 'Work Item'}`;
    }

    /**
     * Computed property for character count display
     */
    get characterCount() {
        const current = this.noteText ? this.noteText.length : 0;
        return `${current} / 1000`;
    }

    /**
     * Computed property to check if character limit exceeded
     */
    get isOverLimit() {
        return this.noteText && this.noteText.length > 1000;
    }
}

