import { LightningElement, api, track } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';

export default class WorkItemHistory extends LightningElement {
    @api workItemId;
    @api initiallyExpanded = false;

    @track isExpanded = false;
    @track historyItems = [];
    @track isLoading = false;
    @track errorMessage = '';

    /**
     * Initialize expanded state on component load
     */
    connectedCallback() {
        this.isExpanded = this.initiallyExpanded;
    }

    /**
     * Handle toggle history expand/collapse
     */
    handleToggleHistory() {
        this.isExpanded = !this.isExpanded;

        // Load history on first expand
        if (this.isExpanded && this.historyItems.length === 0) {
            this.loadHistory();
        }
    }

    /**
     * Load history for the Work Item
     * Note: Phase 1 uses placeholder data
     * Phase 2 will implement Apex controller to query Field History
     */
    loadHistory() {
        this.isLoading = true;

        try {
            // Placeholder history data for Phase 1
            // Phase 2 will replace with actual Field History query via Apex
            this.historyItems = [
                {
                    id: '1',
                    formattedDate: new Date().toLocaleString(),
                    userName: 'System',
                    action: 'Work Item created'
                }
            ];

            this.isLoading = false;
            this.errorMessage = '';
        } catch (error) {
            this.historyItems = [];
            this.isLoading = false;
            this.errorMessage = error.body ? error.body.message : 'An unknown error occurred';
        }
    }

    // === Computed Properties ===

    /**
     * Icon name for expand/collapse button
     */
    get expandIconName() {
        return this.isExpanded ? 'utility:chevrondown' : 'utility:chevronright';
    }

    /**
     * Alt text for expand/collapse icon
     */
    get expandIconAltText() {
        return this.isExpanded ? 'Collapse History' : 'Expand History';
    }

    /**
     * History count for display in header
     */
    get historyCount() {
        return this.historyItems ? this.historyItems.length : 0;
    }

    /**
     * Whether history items exist
     */
    get hasHistory() {
        return !this.isLoading && !this.errorMessage && this.historyItems && this.historyItems.length > 0;
    }

    /**
     * Whether no history items exist
     */
    get hasNoHistory() {
        return !this.isLoading && !this.errorMessage && (!this.historyItems || this.historyItems.length === 0);
    }

    /**
     * Whether an error occurred loading history
     */
    get hasError() {
        return this.errorMessage && this.errorMessage.length > 0;
    }
}

