import { LightningElement, api, track } from 'lwc';
import getWorkItemHistory from '@salesforce/apex/WorkItemController.getWorkItemHistory';
import getNotesForWorkItem from '@salesforce/apex/WorkItemNoteController.getNotesForWorkItem';
import getTimeEntries from '@salesforce/apex/WorkItemController.getTimeEntriesForWorkItem';

export default class WorkItemHistoryModal extends LightningElement {
    @track workItemId;
    @track showModal = false;
    @track historyItems = [];
    @track notes = [];
    @track timeEntries = [];
    @track combinedItems = [];
    @track isLoading = false;
    @track errorMessage = '';
    @track activeTab = 'all';

    /**
     * Open the modal and load history
     * @param {String} workItemId - The ID of the Work Item to load history for
     */
    @api
    openModal(workItemId) {
        this.workItemId = workItemId;
        this.showModal = true;
        this.loadHistory();
    }

    /**
     * Close the modal
     */
    handleClose() {
        this.showModal = false;
        this.activeTab = 'all'; // Reset to All tab when closing
    }

    /**
     * Handle tab change
     */
    handleTabChange(event) {
        this.activeTab = event.target.value;
    }

    /**
     * Load history and notes for the Work Item
     */
    loadHistory() {
        if (!this.workItemId) {
            this.errorMessage = 'Work Item ID is required';
            return;
        }

        this.isLoading = true;
        this.errorMessage = '';

        Promise.all([getWorkItemHistory({ workItemId: this.workItemId }), getNotesForWorkItem({ workItemId: this.workItemId }), getTimeEntries({ workItemId: this.workItemId })])
            .then(([historyData, notesData, timeEntriesData]) => {
                // Transform history data for display
                this.historyItems = historyData.map((item) => {
                    const fieldName = item.Field;
                    const isStatusUpdate = fieldName === 'cgpm__Status__c';

                    return {
                        id: item.Id,
                        type: 'history',
                        isStatusUpdate: isStatusUpdate,
                        isFieldUpdate: !isStatusUpdate,
                        formattedDate: this.formatDateTime(item.CreatedDate),
                        sortDate: new Date(item.CreatedDate),
                        userName: item.CreatedBy.Name,
                        fieldName: fieldName,
                        fieldLabel: this.getFieldLabel(fieldName),
                        action: this.getActionDescription(item),
                        oldValue: this.formatValue(item.OldValue),
                        newValue: this.formatValue(item.NewValue)
                    };
                });

                // Transform notes data for display
                this.notes = notesData.map((note) => {
                    return {
                        id: note.id,
                        type: 'note',
                        isNote: true,
                        formattedDate: this.formatDateTime(note.createdDate),
                        sortDate: new Date(note.createdDate),
                        userName: note.createdByName,
                        noteText: note.noteText
                    };
                });

                // Transform time entries data for display
                this.timeEntries = timeEntriesData.map((entry) => {
                    return {
                        id: entry.id,
                        type: 'timeentry',
                        isTimeEntry: true,
                        timeEntryNumber: entry.timeEntryNumber,
                        formattedDate: this.formatDateTime(entry.createdDate),
                        sortDate: new Date(entry.createdDate),
                        entryDate: this.formatDate(entry.entryDate),
                        hours: entry.hours,
                        description: entry.description,
                        workItemName: entry.workItemName,
                        resourceName: entry.resourceName,
                        createdByName: entry.createdByName
                    };
                });

                // Combine and sort by date (newest first)
                this.combinedItems = [...this.historyItems, ...this.notes, ...this.timeEntries].sort((a, b) => {
                    return b.sortDate - a.sortDate;
                });

                this.isLoading = false;
            })
            .catch((error) => {
                this.historyItems = [];
                this.notes = [];
                this.timeEntries = [];
                this.combinedItems = [];
                this.isLoading = false;
                this.errorMessage = error.body ? error.body.message : 'An unknown error occurred';
            });
    }

    /**
     * Format date-time for display
     */
    formatDateTime(dateTimeString) {
        if (!dateTimeString) {
            return '';
        }
        const date = new Date(dateTimeString);
        return date.toLocaleString();
    }

    /**
     * Format date for display
     */
    formatDate(dateString) {
        if (!dateString) {
            return '';
        }
        const date = new Date(dateString);
        return date.toLocaleDateString();
    }

    /**
     * Format field value for display
     */
    formatValue(value) {
        if (value === null || value === undefined) {
            return '';
        }
        return String(value);
    }

    /**
     * Get user-friendly field label
     */
    getFieldLabel(fieldApiName) {
        const fieldLabels = {
            cgpm__Status__c: 'Status',
            cgpm__Start_Date__c: 'Start Date',
            cgpm__Due_Date__c: 'Due Date',
            cgpm__Estimated_Hours__c: 'Estimated Hours',
            cgpm__Actual_Hours__c: 'Actual Hours',
            cgpm__Work_Item_Name__c: 'Name',
            cgpm__Summary__c: 'Summary',
            cgpm__Parent_Work_Item__c: 'Parent Work Item',
            cgpm__Work_Item_Template__c: 'Template'
        };

        return fieldLabels[fieldApiName] || fieldApiName;
    }

    /**
     * Get action description based on field change
     */
    getActionDescription(historyItem) {
        const field = historyItem.Field;

        // Special handling for created record
        if (field === 'created') {
            return 'Created work item';
        }

        // For field changes, return field-specific descriptions
        const oldVal = historyItem.OldValue;
        const newVal = historyItem.NewValue;

        if (!oldVal && newVal) {
            return `Set ${this.getFieldLabel(field)}`;
        } else if (oldVal && !newVal) {
            return `Cleared ${this.getFieldLabel(field)}`;
        } else {
            return `Changed ${this.getFieldLabel(field)}`;
        }
    }

    // === Computed Properties ===

    /**
     * Tab options for lightning-tabset
     */
    get tabOptions() {
        return [
            { label: 'All', value: 'all' },
            { label: 'Notes', value: 'notes' },
            { label: 'Status Updates', value: 'status' },
            { label: 'Field Updates', value: 'fields' }
        ];
    }

    /**
     * Filtered items based on active tab
     */
    get filteredItems() {
        if (!this.combinedItems || this.combinedItems.length === 0) {
            return [];
        }

        switch (this.activeTab) {
            case 'notes':
                return this.combinedItems.filter((item) => item.isNote);
            case 'timeentries':
                return this.combinedItems.filter((item) => item.isTimeEntry);
            case 'fields':
                return this.combinedItems.filter((item) => item.isFieldUpdate || item.isStatusUpdate);
            case 'all':
            default:
                return this.combinedItems;
        }
    }

    /**
     * Whether history items exist
     */
    get hasHistory() {
        return !this.isLoading && !this.errorMessage && this.filteredItems && this.filteredItems.length > 0;
    }

    /**
     * Whether no history items exist
     */
    get hasNoHistory() {
        return !this.isLoading && !this.errorMessage && (!this.filteredItems || this.filteredItems.length === 0);
    }

    /**
     * Whether an error occurred loading history
     */
    get hasError() {
        return this.errorMessage && this.errorMessage.length > 0;
    }
}

