import { LightningElement, api, track } from 'lwc';

export default class WorkItemGanttTimeline extends LightningElement {
    _timelineBounds;
    _previousBoundsKey;
    _parentStartDate;
    _parentDueDate;

    @track timelineColumns = [];
    @track monthHeaders = [];

    @api
    get parentStartDate() {
        return this._parentStartDate;
    }
    set parentStartDate(value) {
        this._parentStartDate = value;
        this.buildTimeline();
    }

    @api
    get parentDueDate() {
        return this._parentDueDate;
    }
    set parentDueDate(value) {
        this._parentDueDate = value;
        this.buildTimeline();
    }

    @api
    get timelineBounds() {
        return this._timelineBounds;
    }

    set timelineBounds(value) {
        this._timelineBounds = value;
        this.buildTimeline();
    }

    buildTimeline() {
        if (!this._timelineBounds || !this._timelineBounds.minDate || !this._timelineBounds.maxDate) {
            return;
        }

        const scale = this._timelineBounds.scale || 'week';

        // Prevent unnecessary rebuilds - include parent dates in key
        const boundsKey = `${this._timelineBounds.minDate}-${this._timelineBounds.maxDate}-${scale}-${this._parentStartDate}-${this._parentDueDate}`;
        if (boundsKey === this._previousBoundsKey) {
            return;
        }
        this._previousBoundsKey = boundsKey;

        if (scale === 'day') {
            this.buildDayTimeline();
        } else if (scale === 'week') {
            this.buildWeekTimeline();
        } else if (scale === 'month') {
            this.buildMonthTimeline();
        }
    }

    buildDayTimeline() {
        const columns = [];
        const months = new Map();
        const columnWidth = 80; // Day columns are 80px (2x wider)

        const startDate = this.parseLocalDate(this._timelineBounds.minDate);
        const endDate = this.parseLocalDate(this._timelineBounds.maxDate);
        const today = this.parseLocalDate(this._timelineBounds.today);

        let currentDate = new Date(startDate);
        let columnIndex = 0;

        while (currentDate <= endDate) {
            const dateStr = currentDate.toISOString().split('T')[0];
            const monthKey = `${currentDate.getFullYear()}-${currentDate.getMonth()}`;
            const isToday = dateStr === this._timelineBounds.today;
            const isWeekend = currentDate.getDay() === 0 || currentDate.getDay() === 6;
            const isInParentRange = this.isDateInParentRange(dateStr);

            columns.push({
                date: dateStr,
                label: currentDate.getDate(),
                isToday,
                isWeekend,
                columnIndex,
                class: this.getColumnClass(isToday, isWeekend, isInParentRange),
                style: `width: ${columnWidth}px;`
            });

            // Track months for header row
            if (!months.has(monthKey)) {
                months.set(monthKey, {
                    label: currentDate.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }),
                    startColumn: columnIndex,
                    colspan: 0,
                    columnWidth: columnWidth
                });
            }

            const monthData = months.get(monthKey);
            monthData.colspan++;

            currentDate.setDate(currentDate.getDate() + 1);
            columnIndex++;
        }

        this.timelineColumns = columns;
        this.monthHeaders = Array.from(months.values()).map((month) => ({
            ...month,
            style: `width: ${month.colspan * month.columnWidth}px;`
        }));
    }

    buildWeekTimeline() {
        const columns = [];
        const months = new Map();
        const columnWidth = 160; // Week columns are 160px (2x wider)

        const startDate = this.parseLocalDate(this._timelineBounds.minDate);
        const endDate = this.parseLocalDate(this._timelineBounds.maxDate);
        const today = this.parseLocalDate(this._timelineBounds.today);

        // Find the Monday of the week containing startDate
        let currentDate = new Date(startDate);
        const dayOfWeek = currentDate.getDay();
        const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
        currentDate.setDate(currentDate.getDate() + daysToMonday);

        let columnIndex = 0;

        while (currentDate <= endDate) {
            const dateStr = currentDate.toISOString().split('T')[0];
            const monthKey = `${currentDate.getFullYear()}-${currentDate.getMonth()}`;
            const isThisWeek = this.isDateInWeek(today, currentDate);
            const isInParentRange = this.isWeekInParentRange(dateStr);

            const weekLabel = currentDate.toLocaleDateString('en-US', { month: 'numeric', day: 'numeric' });

            columns.push({
                date: dateStr,
                label: weekLabel,
                isThisWeek,
                columnIndex,
                class: this.getColumnClass(isThisWeek, false, isInParentRange),
                style: `width: ${columnWidth}px;`
            });

            // Track months for header row
            if (!months.has(monthKey)) {
                months.set(monthKey, {
                    label: currentDate.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }),
                    startColumn: columnIndex,
                    colspan: 0,
                    columnWidth: columnWidth
                });
            }

            const monthData = months.get(monthKey);
            monthData.colspan++;

            currentDate.setDate(currentDate.getDate() + 7);
            columnIndex++;
        }

        this.timelineColumns = columns;
        this.monthHeaders = Array.from(months.values()).map((month) => ({
            ...month,
            style: `width: ${month.colspan * month.columnWidth}px;`
        }));
    }

    buildMonthTimeline() {
        const columns = [];
        const years = new Map();
        const columnWidth = 360; // Month columns are 360px (3x wider)

        const startDate = this.parseLocalDate(this._timelineBounds.minDate);
        const endDate = this.parseLocalDate(this._timelineBounds.maxDate);
        const today = this.parseLocalDate(this._timelineBounds.today);

        // Start at first day of month
        let currentDate = new Date(startDate.getFullYear(), startDate.getMonth(), 1);

        let columnIndex = 0;

        while (currentDate <= endDate) {
            const dateStr = currentDate.toISOString().split('T')[0];
            const yearKey = currentDate.getFullYear().toString();
            const isThisMonth = currentDate.getMonth() === today.getMonth() && currentDate.getFullYear() === today.getFullYear();
            const isInParentRange = this.isMonthInParentRange(dateStr);

            const monthLabel = currentDate.toLocaleDateString('en-US', { month: 'short' });

            columns.push({
                date: dateStr,
                label: monthLabel,
                isThisMonth,
                columnIndex,
                class: this.getColumnClass(isThisMonth, false, isInParentRange),
                style: `width: ${columnWidth}px;`
            });

            // Track years for header row
            if (!years.has(yearKey)) {
                years.set(yearKey, {
                    label: yearKey,
                    startColumn: columnIndex,
                    colspan: 0,
                    columnWidth: columnWidth
                });
            }

            const yearData = years.get(yearKey);
            yearData.colspan++;

            currentDate.setMonth(currentDate.getMonth() + 1);
            columnIndex++;
        }

        this.timelineColumns = columns;
        this.monthHeaders = Array.from(years.values()).map((year) => ({
            ...year,
            style: `width: ${year.colspan * year.columnWidth}px;`
        }));
    }

    parseLocalDate(dateString) {
        // Parse YYYY-MM-DD as local date (not UTC)
        if (!dateString) {
            return null;
        }
        const [year, month, day] = dateString.split('-');
        return new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
    }

    isDateInWeek(checkDate, weekStartDate) {
        const weekStart = new Date(weekStartDate);
        const weekEnd = new Date(weekStartDate);
        weekEnd.setDate(weekEnd.getDate() + 6);

        return checkDate >= weekStart && checkDate <= weekEnd;
    }

    getColumnClass(isToday, isWeekend, isInParentRange = false) {
        const classes = ['timeline-column'];
        if (isToday) {
            classes.push('today-column');
        }
        if (isWeekend) {
            classes.push('weekend-column');
        }
        if (isInParentRange) {
            classes.push('parent-range-column');
        }
        return classes.join(' ');
    }

    isDateInParentRange(dateStr) {
        if (!this._parentStartDate || !this._parentDueDate || !dateStr) {
            return false;
        }

        const date = this.parseLocalDate(dateStr);
        const startDate = this.parseLocalDate(this._parentStartDate);
        const endDate = this.parseLocalDate(this._parentDueDate);

        return date >= startDate && date <= endDate;
    }

    isWeekInParentRange(weekStartDate) {
        if (!this._parentStartDate || !this._parentDueDate || !weekStartDate) {
            return false;
        }

        const weekStart = this.parseLocalDate(weekStartDate);
        const weekEnd = new Date(weekStart);
        weekEnd.setDate(weekEnd.getDate() + 6);

        const parentStart = this.parseLocalDate(this._parentStartDate);
        const parentEnd = this.parseLocalDate(this._parentDueDate);

        // Week is in range if it overlaps with parent range
        return weekStart <= parentEnd && weekEnd >= parentStart;
    }

    isMonthInParentRange(monthStartDate) {
        if (!this._parentStartDate || !this._parentDueDate || !monthStartDate) {
            return false;
        }

        const monthStart = this.parseLocalDate(monthStartDate);
        const monthEnd = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 0);

        const parentStart = this.parseLocalDate(this._parentStartDate);
        const parentEnd = this.parseLocalDate(this._parentDueDate);

        // Month is in range if it overlaps with parent range
        return monthStart <= parentEnd && monthEnd >= parentStart;
    }

    get totalColumns() {
        return this.timelineColumns.length;
    }

    get gridTemplateColumns() {
        return `200px repeat(${this.totalColumns}, 40px)`;
    }
}

