import { api, wire, track } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import getProjectRoles from '@salesforce/apex/ProjectRoleController.getProjectRoles';
import getActiveResourceTypeTemplates from '@salesforce/apex/ProjectRoleController.getActiveResourceTypeTemplates';
import saveProjectRole from '@salesforce/apex/ProjectRoleController.saveProjectRole';
import deleteProjectRole from '@salesforce/apex/ProjectRoleController.deleteProjectRole';
import getDefaultBillingRate from '@salesforce/apex/ProjectRoleController.getDefaultBillingRate';
import BaseComponent from 'c/baseComponent';

export default class ProjectRoleManager extends BaseComponent {
    @api recordId; // Project Id
    @track projectRoles = [];
    @track resourceTypeTemplates = [];
    @track editingRole = null;
    @track isAddMode = false;
    @track isLoading = false;
    @track isExpanded = false; // Controls expanded/collapsed state - default to collapsed

    // Form fields for add/edit
    @track formData = {
        resourceTypeTemplateId: '',
        roleName: '',
        billingRate: null
    };

    wiredProjectRolesResult;

    connectedCallback() {
        this.isExpanded = this.getLocalState(this.recordId, 'ProjectRoleManager.isExpanded', this.isExpanded);
    }

    // Wire project roles
    @wire(getProjectRoles, { projectId: '$recordId' })
    wiredProjectRoles(result) {
        this.wiredProjectRolesResult = result;
        if (result.data) {
            this.projectRoles = result.data.map((role) => {
                const formattedBillingRate = role.cgpm__Billing_Rate__c
                    ? new Intl.NumberFormat('en-US', {
                          style: 'currency',
                          currency: 'USD'
                      }).format(role.cgpm__Billing_Rate__c)
                    : '';

                return {
                    ...role,
                    formattedBillingRate
                };
            });
            this.isLoading = false;
        } else if (result.error) {
            this.showError('Error loading project roles: ' + result.error.body.message);
            this.isLoading = false;
        }
    }

    // Wire active resource type templates
    @wire(getActiveResourceTypeTemplates)
    wiredResourceTypeTemplates({ data, error }) {
        if (data) {
            this.resourceTypeTemplates = data;
        } else if (error) {
            this.showError('Error loading resource type templates: ' + error.body.message);
        }
    }

    get hasRoles() {
        return this.projectRoles && this.projectRoles.length > 0;
    }

    get isFormOpen() {
        return this.isAddMode || this.editingRole !== null;
    }

    get formTitle() {
        return this.isAddMode ? 'Add Project Role' : 'Edit Project Role';
    }

    get saveButtonLabel() {
        return this.isAddMode ? 'Add' : 'Save';
    }

    get resourceTypeTemplateOptions() {
        return this.resourceTypeTemplates.map((template) => ({
            label: `${template.Name} (${template.cgpm__Resource_Classification__c})`,
            value: template.Id
        }));
    }

    get toggleIconName() {
        return this.isExpanded ? 'utility:chevrondown' : 'utility:chevronright';
    }

    get toggleTitle() {
        return this.isExpanded ? 'Collapse' : 'Expand';
    }

    handleToggle() {
        this.isExpanded = !this.isExpanded;
        this.setLocalState(this.recordId, 'ProjectRoleManager.isExpanded', this.isExpanded);
    }

    handleAddNew() {
        this.isAddMode = true;
        this.editingRole = null;
        this.formData = {
            resourceTypeTemplateId: '',
            roleName: '',
            billingRate: null
        };
        this.isExpanded = true; // Expand when opening form
    }

    handleEdit(event) {
        const roleId = event.currentTarget.dataset.id;
        const role = this.projectRoles.find((r) => r.Id === roleId);

        if (role) {
            this.isAddMode = false;
            this.editingRole = role;
            this.formData = {
                resourceTypeTemplateId: role.cgpm__Resource_Type_Template__c,
                roleName: role.Name,
                billingRate: role.cgpm__Billing_Rate__c
            };
            this.isExpanded = true; // Expand when opening form
        }
    }

    handleDelete(event) {
        const roleId = event.currentTarget.dataset.id;
        const role = this.projectRoles.find((r) => r.Id === roleId);

        if (role && confirm(`Are you sure you want to delete the role "${role.Name}"?`)) {
            this.isLoading = true;
            deleteProjectRole({ projectRoleId: roleId })
                .then(() => {
                    this.showSuccess('Project role deleted successfully');
                    return refreshApex(this.wiredProjectRolesResult);
                })
                .catch((error) => {
                    this.showError('Error deleting project role: ' + error.body.message);
                })
                .finally(() => {
                    this.isLoading = false;
                });
        }
    }

    handleFieldChange(event) {
        const field = event.currentTarget.dataset.field;
        this.formData[field] = event.detail.value;
    }

    handleTemplateChange(event) {
        const templateId = event.detail.value;
        this.formData.resourceTypeTemplateId = templateId;

        // Auto-populate Role Name from template name
        const template = this.resourceTypeTemplates.find((t) => t.Id === templateId);
        if (template) {
            this.formData.roleName = template.Name;
        }

        // Fetch and auto-populate default billing rate
        if (templateId) {
            getDefaultBillingRate({ templateId })
                .then((result) => {
                    if (result !== null && result !== undefined) {
                        this.formData.billingRate = result;
                    }
                })
                .catch((error) => {
                    console.error('Error fetching default billing rate:', error);
                });
        }
    }

    handleSave() {
        // Validate required fields
        if (!this.formData.resourceTypeTemplateId) {
            this.showError('Please select a Resource Type Template');
            return;
        }

        if (!this.formData.roleName) {
            this.showError('Please enter a Role Name');
            return;
        }

        this.isLoading = true;

        const projectRole = {
            cgpm__Project__c: this.recordId,
            Name: this.formData.roleName,
            cgpm__Resource_Type_Template__c: this.formData.resourceTypeTemplateId,
            cgpm__Billing_Rate__c: this.formData.billingRate
        };

        // If editing, include the Id
        if (this.editingRole) {
            projectRole.Id = this.editingRole.Id;
        }

        saveProjectRole({ projectRole })
            .then(() => {
                const message = this.isAddMode ? 'Project role added successfully' : 'Project role updated successfully';
                this.showSuccess(message);
                this.handleCancel();
                return refreshApex(this.wiredProjectRolesResult);
            })
            .catch((error) => {
                this.showError('Error saving project role: ' + error.body.message);
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    handleCancel() {
        this.isAddMode = false;
        this.editingRole = null;
        this.formData = {
            resourceTypeTemplateId: '',
            roleName: '',
            billingRate: null
        };
    }

    formatDate(dateString) {
        if (!dateString) {
            return '';
        }
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    }
}

