     1→import { api, wire } from 'lwc';
     2→import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
     3→import WORK_ITEM_CHANNEL from '@salesforce/messageChannel/WorkItemEventChannel__c';
     4→import WORK_ITEM_NAME_FIELD from '@salesforce/schema/Work_Item__c.Work_Item_Name__c';
     5→import { IsConsoleNavigation, EnclosingTabId, getFocusedTabInfo, getAllTabInfo, setTabLabel, setTabIcon, refreshTab } from 'lightning/platformWorkspaceApi';
     6→import BaseComponent from 'c/baseComponent';
     7→
     8→/**
     9→ * Utility component to enhance Work Item messaging in Console apps
    10→ * Monitors tab focus changes, refreshes components, and updates tab labels
    11→ */
    12→export default class WorkItemConsoleHelper extends BaseComponent {
    13→    @api recordId;
    14→    @api objectApiName;
    15→
    16→    @wire(IsConsoleNavigation)
    17→    isConsoleNavigation;
    18→
    19→    @wire(EnclosingTabId)
    20→    enclosingTabId;
    21→
    22→    @wire(getRecord, {
    23→        recordId: '$recordId',
    24→        fields: [WORK_ITEM_NAME_FIELD]
    25→    })
    26→    wiredRecord({ data, error }) {
    27→        if (error && this.objectApiName === 'cgpm__Work_Item__c') {
    28→            console.error('workItemConsoleHelper: Error loading record', error);
    29→        }
    30→
    31→        if (data && this.objectApiName === 'cgpm__Work_Item__c') {
    32→            const workItemName = getFieldValue(data, WORK_ITEM_NAME_FIELD);
    33→            //console.log('workItemConsoleHelper: Work Item name from record', workItemName);
    34→            if (workItemName) {
    35→                this.workItemName = workItemName;
    36→                this.setCurrentTabLabel(workItemName);
    37→            }
    38→        } else if (data) {
    39→            //console.log('workItemConsoleHelper: Not a Work Item page, objectApiName:', this.objectApiName);
    40→        }
    41→    }
    42→
    43→    focusCheckInterval;
    44→    lastFocusedTabId = null;
    45→    workItemName = null;
    46→    tabLabelSet = false;
    47→
    48→    connectedCallback() {
    49→        this.startFocusMonitoring();
    50→    }
    51→
    52→    /**
    53→     * Set the label of the current tab
    54→     */
    55→    async setCurrentTabLabel(label) {
    56→        if (!this.isConsoleNavigation) {
    57→            //console.log('workItemConsoleHelper: Not in console navigation');
    58→            return;
    59→        }
    60→
    61→        if (!this.enclosingTabId) {
    62→            // console.log('workItemConsoleHelper: Tab ID not ready yet, will retry in focus monitor');
    63→            return;
    64→        }
    65→
    66→        if (this.tabLabelSet) {
    67→            //console.log('workItemConsoleHelper: Tab label already set');
    68→            return;
    69→        }
    70→
    71→        try {
    72→            const { tabId } = await getFocusedTabInfo();
    73→            setTabLabel(tabId, label);
    74→            this.tabLabelSet = true;
    75→            //console.log('workItemConsoleHelper: Tab label set successfully');
    76→        } catch (error) {
    77→            console.error('workItemConsoleHelper: Error setting tab label', error);
    78→            // Mark as set even on error to prevent repeated attempts
    79→            this.tabLabelSet = true;
    80→        }
    81→    }
    82→
    83→    disconnectedCallback() {
    84→        if (this.focusCheckInterval) {
    85→            clearInterval(this.focusCheckInterval);
    86→        }
    87→    }
    88→
    89→    /**
    90→     * Monitor when this tab becomes focused
    91→     */
    92→    startFocusMonitoring() {
    93→        if (!this.isConsoleNavigation) {
    94→            return;
    95→        }
    96→
    97→        // Check if this tab is focused every 1 second
    98→        this.focusCheckInterval = setInterval(async () => {
    99→            try {
   100→                // Try to set tab label if we have the name but haven't set it yet
   101→                if (this.workItemName && !this.tabLabelSet && this.enclosingTabId) {
   102→                    await this.setCurrentTabLabel(this.workItemName);
   103→                }
   104→
   105→                const focusedTab = await getFocusedTabInfo();
   106→
   107→                // If this tab just became focused, publish refresh
   108→                if (focusedTab && focusedTab.tabId === this.enclosingTabId && this.lastFocusedTabId !== focusedTab.tabId) {
   109→                    this.lastFocusedTabId = focusedTab.tabId;
   110→                    this.publishRefresh();
   111→                }
   112→                // Track when we lose focus
   113→                else if (focusedTab && focusedTab.tabId !== this.enclosingTabId) {
   114→                    this.lastFocusedTabId = focusedTab.tabId;
   115→                }
   116→            } catch (error) {
   117→                // Silently fail if not in console context
   118→            }
   119→        }, 1000);
   120→    }
   121→
   122→    /**
   123→     * Publish refresh message to update components on the page
   124→     */
   125→    publishRefresh() {
   126→        if (!this.isConsoleNavigation || !this.messageContext) {
   127→            return;
   128→        }
   129→
   130→        this.notify('refresh', {
   131→            source: 'console-tab-focus'
   132→        });
   133→    }
   134→
   135→    /**
   136→     * Publish a Work Item update and refresh all open tabs showing that Work Item
   137→     */
   138→    @api
   139→    async publishAndRefreshTabs(action, workItemId, projectId, changes = null, workItemData = null) {
   140→        // Publish the standard LMS message
   141→        const message = {
   142→            workItemId,
   143→            projectId,
   144→            changes,
   145→            workItemData
   146→        };
   147→        this.notify(action, message);
   148→
   149→        // If in console, refresh all tabs showing this Work Item
   150→        if (this.isConsoleNavigation) {
   151→            try {
   152→                const allTabs = await getAllTabInfo();
   153→
   154→                // Find tabs showing this Work Item's record page
   155→                const workItemTabs = allTabs.filter((tab) => tab.recordId === workItemId);
   156→
   157→                // Refresh each matching tab
   158→                for (const tab of workItemTabs) {
   159→                    await refreshTab(tab.tabId);
   160→                }
   161→            } catch (error) {
   162→                console.error('Error refreshing console tabs:', error);
   163→            }
   164→        }
   165→    }
   166→
   167→    /**
   168→     * Update the tab label when a Work Item name changes
   169→     */
   170→    @api
   171→    async updateTabLabel(workItemId, newName) {
   172→        if (!this.isConsoleNavigation) {
   173→            return;
   174→        }
   175→
   176→        try {
   177→            const { tabId } = await getFocusedTabInfo();
   178→            setTabLabel(tabId, newName);
   179→        } catch (error) {
   180→            console.error('Error updating tab label:', error);
   181→        }
   182→    }
   183→
   184→    /**
   185→     * Update tab icon based on Work Item status
   186→     */
   187→    @api
   188→    async updateTabIcon(workItemId, status) {
   189→        if (!this.isConsoleNavigation) {
   190→            return;
   191→        }
   192→
   193→        // todo: define icons for each status on the template
   194→        const iconMap = {
   195→            Complete: 'standard:task2',
   196→            'In Progress': 'standard:work_order',
   197→            'Not Started': 'standard:work_plan',
   198→            'On Hold': 'standard:timeslot',
   199→            Cancelled: 'standard:cancel_checkout'
   200→        };
   201→
   202→        try {
