import { api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import WORK_ITEM_CHANNEL from '@salesforce/messageChannel/WorkItemEventChannel__c';
import WORK_ITEM_NAME_FIELD from '@salesforce/schema/Work_Item__c.Work_Item_Name__c';
import { IsConsoleNavigation, EnclosingTabId, getFocusedTabInfo, getAllTabInfo, setTabLabel, setTabIcon, refreshTab } from 'lightning/platformWorkspaceApi';
import BaseComponent from 'c/baseComponent';

/**
 * Utility component to enhance Work Item messaging in Console apps
 * Monitors tab focus changes, refreshes components, and updates tab labels
 */
export default class WorkItemConsoleHelper extends BaseComponent {
    @api recordId;
    @api objectApiName;

    @wire(IsConsoleNavigation)
    isConsoleNavigation;

    @wire(EnclosingTabId)
    enclosingTabId;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: [WORK_ITEM_NAME_FIELD]
    })
    wiredRecord({ data, error }) {
        if (error && this.objectApiName === 'cgpm__Work_Item__c') {
            console.error('workItemConsoleHelper: Error loading record', error);
        }

        if (data && this.objectApiName === 'cgpm__Work_Item__c') {
            const workItemName = getFieldValue(data, WORK_ITEM_NAME_FIELD);
            //console.log('workItemConsoleHelper: Work Item name from record', workItemName);
            if (workItemName) {
                this.workItemName = workItemName;
                this.setCurrentTabLabel(workItemName);
            }
        } else if (data) {
            //console.log('workItemConsoleHelper: Not a Work Item page, objectApiName:', this.objectApiName);
        }
    }

    focusCheckInterval;
    lastFocusedTabId = null;
    workItemName = null;
    tabLabelSet = false;

    connectedCallback() {
        this.startFocusMonitoring();
    }

    /**
     * Set the label of the current tab
     */
    async setCurrentTabLabel(label) {
        if (!this.isConsoleNavigation) {
            //console.log('workItemConsoleHelper: Not in console navigation');
            return;
        }

        if (!this.enclosingTabId) {
            // console.log('workItemConsoleHelper: Tab ID not ready yet, will retry in focus monitor');
            return;
        }

        if (this.tabLabelSet) {
            //console.log('workItemConsoleHelper: Tab label already set');
            return;
        }

        try {
            const { tabId } = await getFocusedTabInfo();
            setTabLabel(tabId, label);
            this.tabLabelSet = true;
            //console.log('workItemConsoleHelper: Tab label set successfully');
        } catch (error) {
            console.error('workItemConsoleHelper: Error setting tab label', error);
            // Mark as set even on error to prevent repeated attempts
            this.tabLabelSet = true;
        }
    }

    disconnectedCallback() {
        if (this.focusCheckInterval) {
            clearInterval(this.focusCheckInterval);
        }
    }

    /**
     * Monitor when this tab becomes focused
     */
    startFocusMonitoring() {
        if (!this.isConsoleNavigation) {
            return;
        }

        // Check if this tab is focused every 1 second
        this.focusCheckInterval = setInterval(async () => {
            try {
                // Try to set tab label if we have the name but haven't set it yet
                if (this.workItemName && !this.tabLabelSet && this.enclosingTabId) {
                    await this.setCurrentTabLabel(this.workItemName);
                }

                const focusedTab = await getFocusedTabInfo();

                // If this tab just became focused, publish refresh
                if (focusedTab && focusedTab.tabId === this.enclosingTabId && this.lastFocusedTabId !== focusedTab.tabId) {
                    this.lastFocusedTabId = focusedTab.tabId;
                    this.publishRefresh();
                }
                // Track when we lose focus
                else if (focusedTab && focusedTab.tabId !== this.enclosingTabId) {
                    this.lastFocusedTabId = focusedTab.tabId;
                }
            } catch (error) {
                // Silently fail if not in console context
            }
        }, 1000);
    }

    /**
     * Publish refresh message to update components on the page
     */
    publishRefresh() {
        if (!this.isConsoleNavigation || !this.messageContext) {
            return;
        }

        this.notify('refresh', {
            source: 'console-tab-focus'
        });
    }

    /**
     * Publish a Work Item update and refresh all open tabs showing that Work Item
     */
    @api
    async publishAndRefreshTabs(action, workItemId, projectId, changes = null, workItemData = null) {
        // Publish the standard LMS message
        const message = {
            workItemId,
            projectId,
            changes,
            workItemData
        };
        this.notify(action, message);

        // If in console, refresh all tabs showing this Work Item
        if (this.isConsoleNavigation) {
            try {
                const allTabs = await getAllTabInfo();

                // Find tabs showing this Work Item's record page
                const workItemTabs = allTabs.filter((tab) => tab.recordId === workItemId);

                // Refresh each matching tab
                for (const tab of workItemTabs) {
                    await refreshTab(tab.tabId);
                }
            } catch (error) {
                console.error('Error refreshing console tabs:', error);
            }
        }
    }

    /**
     * Update the tab label when a Work Item name changes
     */
    @api
    async updateTabLabel(workItemId, newName) {
        if (!this.isConsoleNavigation) {
            return;
        }

        try {
            const { tabId } = await getFocusedTabInfo();
            setTabLabel(tabId, newName);
        } catch (error) {
            console.error('Error updating tab label:', error);
        }
    }

    /**
     * Update tab icon based on Work Item status
     */
    @api
    async updateTabIcon(workItemId, status) {
        if (!this.isConsoleNavigation) {
            return;
        }

        // todo: define icons for each status on the template
        const iconMap = {
            Complete: 'standard:task2',
            'In Progress': 'standard:work_order',
            'Not Started': 'standard:work_plan',
            'On Hold': 'standard:timeslot',
            Cancelled: 'standard:cancel_checkout'
        };

        try {
            const allTabs = await getAllTabInfo();
            const workItemTab = allTabs.find((tab) => tab.recordId === workItemId);

            if (workItemTab && iconMap[status]) {
                await setTabIcon(workItemTab.tabId, iconMap[status]);
            }
        } catch (error) {
            console.error('Error updating tab icon:', error);
        }
    }

    /**
     * Get the current focused tab information
     */
    @api
    async getFocusedWorkItem() {
        if (!this.isConsoleNavigation) {
            return null;
        }

        try {
            const focusedTab = await getFocusedTabInfo();
            return focusedTab.recordId || null;
        } catch (error) {
            console.error('Error getting focused tab:', error);
            return null;
        }
    }
}

